cd /workspace && node -e "
const mammoth = require('mammoth');
const fs = require('fs');

mammoth.extractRawText({ path: './testbed/docs/Meeting_Notes_2024_06.docx' })
  .then(result => {
    const paragraphs = result.value
      .split(/\n/)
      .filter(line => line.trim() !== '')
      .join('\n\n');

    fs.writeFileSync('./Meeting_Notes_2024_06.txt', paragraphs, 'utf-8');
    const count = paragraphs.split('\n\n').length;
    console.log('Extracted ' + count + ' paragraphs → Meeting_Notes_2024_06.txt');
  })
  .catch(err => { console.error(err); process.exit(1); });
"
